transforms.code:
security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureAssets']['enabled']: 
		canCreate = True
		canEdit = True if len(value['data']) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

config.script:
if self.view.custom.orderStates.userAction.canUpdate:
	workOrderStatusId = self.props.data[event.row]['workOrderStatusId']		
	if event.column in ('enabled', 'isActive', 'canSchedule', 'canExecute'):
		retVal, msg = system.kanoa.order.updateProductionOrderStateField(workOrderStatusId, event.column, event.value, self.view.custom.security.userId)
		if msg: system.perspective.sendMessage('showFailerToast', {'message': 'Failed to update the order state. %s'%msg})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Order State has been updated'})		
	else: system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing')
else: system.perspective.sendMessage('showFailerToast', 'No permissions to update order states')

self.view.refreshBinding("custom.orderStates.data")
self.props.selection.selectedRow = None	
self.props.selection.selectedCol = None	

return

transforms.code:

def buildElement(value, fontWeight, foreColor, bgColor):
	style = {}
	if fontWeight is not None:	style.update({"fontWeight": fontWeight})		
	if foreColor is not None: style.update({"color": foreColor}) 
	else: style.update({"color": system.kanoa.utilities.getContrastingColor(bgColor)})
	if bgColor is not None: style.update({'backgroundColor': bgColor})
	style.update({'borderColor': bgColor or '#000000', 'borderRadius': '4px', 'margin': '1px'})	
	return {'value': value, 'style':style}

orderStates = system.kanoa.utilities.convertDatasetToJSON(value)
for orderState in orderStates:
	orderState['workOrderStatusName'] = buildElement(orderState['workOrderStatusName'], None, None, orderState['statusColor'])
	orderState['lastUpdated'] = '%s by %s'%(system.date.format(orderState['changedDate'] or orderState['createdDate'] or system.date.now(), 'YY-MM-dd HH:mm'), orderState['changedByUser'] or orderState['createdByUser'])

return orderStates

customMethods.script:

for row in self.view.custom.orderStates.selectedData:
	retVal, msg = system.kanoa.order.deleteProductionOrderState(row['workOrderStatusId'], self.view.custom.security.userId)
	if msg: system.perspective.sendMessage('showWarningToast', {'message': msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Order state %s has been deleted'%row['workOrderStatusName']})

self.view.refreshBinding("custom.orderStates.data")

return
